mapper.select:
SELECT id, doc_no, period_type, from_date, to_date, store, customer_code, customer_branch,
       status, process_status, created_by, released_at, created_at, updated_at
FROM customer_billing_request WHERE id = #{id}

mapper.update:
UPDATE customer_billing_request_detail
SET actual_return_qty = #{actualReturnQty}
WHERE id = #{detailId}

mapper.select:
SELECT sku, location, sales_qty, return_qty
FROM unpost_staging_inventory
WHERE location = #{store}

    AND sku IN (
        SELECT DISTINCT sku FROM customer_consignment_inventory
        WHERE issue_from_store = #{store}
          AND customer_code = #{customerCode}
    )
